const skus = $input.all().map(({json}) => String(json.sku));
if (skus.length !== 5 || new Set(skus).size !== 5) throw new Error('Expected exactly five unique canonical SKUs');
const business_date = $now.setZone('Europe/Moscow').minus({days:1}).toISODate();
return [{json:{skus,business_date,request_body:{date_from:business_date,date_to:business_date,metrics:['revenue','ordered_units'],dimension:['sku','day'],filters:[],limit:100,offset:0}}}];

const request = $items('Build Batched Analytics Request')[0].json;
const data = $json.result?.data;
if (!Array.isArray(data)) throw new Error('Seller Analytics returned no result.data');
const allowed = new Set(request.skus);
const rows = data.map((row) => {
  const sku = String(row.dimensions?.[0]?.id ?? '');
  const businessDate = String(row.dimensions?.[1]?.id ?? '');
  if (!allowed.has(sku) || businessDate !== request.business_date || !Array.isArray(row.metrics) || row.metrics.length !== 2) throw new Error('Seller Analytics attribution/metric contract mismatch');
  return {sku:Number(sku),ordered_revenue:row.metrics[0],ordered_units:row.metrics[1]};
});
const now = new Date().toISOString();
return [{json:{collection_ref:`seller-analytics-day-${request.business_date}`,collected_at:now,business_date:request.business_date,rows,persist:true}}];
